import org.slf4j.MDC;

import io.opentelemetry.api.trace.Span;
import io.opentelemetry.api.trace.SpanContext;
import io.opentelemetry.api.trace.Tracer;
import io.opentelemetry.context.Scope;
import io.opentelemetry.sdk.testing.junit5.OpenTelemetryExtension;

class TracingQueryLoggingContextTest {

	@RegisterExtension
	static final OpenTelemetryExtension otelTesting = OpenTelemetryExtension.create();

	private final Map<String, String> originalMdc = MDC.getCopyOfContextMap();

	@AfterEach
	void restoreMdc() {
		if (originalMdc == null) {
			MDC.clear();
		} else {
			MDC.setContextMap(originalMdc);
		}
	}

	@ParameterizedTest
	@EnumSource(QueryForm.class)
	void queryEvaluationPublishesItsRepositoryAndSpanThenRestoresCallerContext(QueryForm form) {
		MDC.put("org.eclipse.rdf4j.repositoryId", "outer-repo");
		MDC.put("traceId", "outer-trace");
		MDC.put("spanId", "outer-span");
		MDC.put("unrelated", "caller-value");
		Map<String, String> before = MDC.getCopyOfContextMap();
		AtomicReference<Map<String, String>> observed = new AtomicReference<>();
		AtomicReference<SpanContext> spanContext = new AtomicReference<>();

		evaluate(form, () -> {
			observed.set(readLoggingContext());
			spanContext.set(Span.current().getSpanContext());
		});

		assertThat(observed.get()).containsEntry("org.eclipse.rdf4j.repositoryId", "test-repo")
				.containsEntry("traceId", spanContext.get().getTraceId())
				.containsEntry("spanId", spanContext.get().getSpanId());
		assertThat(spanContext.get().isValid()).isTrue();
		assertThat(MDC.getCopyOfContextMap()).isEqualTo(before);
		assertThat(otelTesting.getSpans()).hasSize(1);
		assertThat(otelTesting.getSpans().getFirst().getSpanContext()).isEqualTo(spanContext.get());
	}

	@Test
	void nestedQueryAndFailureRestoreTheirEnclosingLoggingContext() {
		Map<String, String> before = MDC.getCopyOfContextMap();
		QueryEvaluationException failure = new QueryEvaluationException("query failed");
		BooleanQuery inner = mock(BooleanQuery.class);
		when(inner.evaluate()).thenAnswer(invocation -> {
			assertThat(MDC.get("org.eclipse.rdf4j.repositoryId")).isEqualTo("inner-repo");
			assertThat(MDC.get("spanId")).isEqualTo(Span.current().getSpanContext().getSpanId());
			throw failure;
		});
		BooleanQuery outer = mock(BooleanQuery.class);
		when(outer.evaluate()).thenAnswer(invocation -> {
			Map<String, String> enclosing = MDC.getCopyOfContextMap();
			assertThat(assertThrows(QueryEvaluationException.class,
					() -> tracedBoolean(inner, "inner-repo").evaluate())).isSameAs(failure);
			assertThat(MDC.getCopyOfContextMap()).isEqualTo(enclosing);
			return true;
		});

		assertThat(tracedBoolean(outer, "outer-repo").evaluate()).isTrue();
		if (before == null) {
			assertThat(MDC.getCopyOfContextMap()).isNullOrEmpty();
		} else {
			assertThat(MDC.getCopyOfContextMap()).isEqualTo(before);
		}
	}

	@Test
	void explanationPublishesRepositoryAndCurrentParentTrace() {
		BooleanQuery delegate = mock(BooleanQuery.class);
		AtomicReference<Map<String, String>> observed = new AtomicReference<>();
		when(delegate.explain(Explanation.Level.Executed)).thenAnswer(invocation -> {
			observed.set(readLoggingContext());
			return mock(Explanation.class);
		});
		Span parent = otelTesting.getOpenTelemetry()
				.getTracer("query-log-context-test")
				.spanBuilder("explanation-request")
				.startSpan();
		try (Scope ignored = parent.makeCurrent()) {
			tracedBoolean(delegate, "test-repo").explain(Explanation.Level.Executed);
		} finally {
			parent.end();
		}
		assertThat(observed.get()).containsEntry("org.eclipse.rdf4j.repositoryId", "test-repo")
				.containsEntry("traceId", parent.getSpanContext().getTraceId())
				.containsEntry("spanId", parent.getSpanContext().getSpanId());
	}

	private void evaluate(QueryForm form, Runnable capture) {
		RDF4JOpenTelemetryConfig config = RDF4JOpenTelemetryConfig.defaultConfig();
		Tracer tracer = otelTesting.getOpenTelemetry().getTracer("query-log-context-test");
		switch (form) {
		case BOOLEAN:
			BooleanQuery bool = mock(BooleanQuery.class);
			when(bool.evaluate()).thenAnswer(invocation -> {
				capture.run();
				return true;
			});
			tracedBoolean(bool, "test-repo").evaluate();
			break;
		case TUPLE_RESULT:
		case TUPLE_HANDLER:
			TupleQuery tuple = mock(TupleQuery.class);
			when(tuple.evaluate()).thenAnswer(invocation -> {
				capture.run();
				return mock(TupleQueryResult.class);
			});
			doAnswer(invocation -> {
				capture.run();
				return null;
			}).when(tuple).evaluate(any(TupleQueryResultHandler.class));
			TracingTupleQuery tracedTuple = new TracingTupleQuery(tuple, "SELECT * WHERE {}", "test-repo", config,
					tracer);
			if (form == QueryForm.TUPLE_RESULT) {
				try (TupleQueryResult result = tracedTuple.evaluate()) {
					result.hasNext();
				}
			} else {
				tracedTuple.evaluate(mock(TupleQueryResultHandler.class));
			}
			break;
		case GRAPH_RESULT:
		case GRAPH_HANDLER:
			GraphQuery graph = mock(GraphQuery.class);
			when(graph.evaluate()).thenAnswer(invocation -> {
				capture.run();
				return mock(GraphQueryResult.class);
			});
			doAnswer(invocation -> {
				capture.run();
				return null;
			}).when(graph).evaluate(any(RDFHandler.class));
			TracingGraphQuery tracedGraph = new TracingGraphQuery(graph, "CONSTRUCT {} WHERE {}", "test-repo", config,
					tracer);
			if (form == QueryForm.GRAPH_RESULT) {
				try (GraphQueryResult result = tracedGraph.evaluate()) {
					result.hasNext();
				}
			} else {
				tracedGraph.evaluate(mock(RDFHandler.class));
			}
			break;
		}
	}

	private TracingBooleanQuery tracedBoolean(BooleanQuery query, String repositoryId) {
		return new TracingBooleanQuery(query, "ASK {}", repositoryId,
				RDF4JOpenTelemetryConfig.defaultConfig(),
				otelTesting.getOpenTelemetry().getTracer("query-log-context-test"));
	}

	private Map<String, String> readLoggingContext() {
		Map<String, String> context = new HashMap<>();
		context.put("org.eclipse.rdf4j.repositoryId", MDC.get("org.eclipse.rdf4j.repositoryId"));
		context.put("traceId", MDC.get("traceId"));
		context.put("spanId", MDC.get("spanId"));
		return context;
	}

	private enum QueryForm {
		BOOLEAN,
		TUPLE_RESULT,
		TUPLE_HANDLER,
		GRAPH_RESULT,
		GRAPH_HANDLER
	}
}
